use aap::caps::http_client;
use aap::caps::state_read;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encodes a value for use as a URL query component.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // The subscription list is read from the 'subscriptions' store under the
        // key "urls", one URL per line. A missing key yields an empty list, so
        // `urls` is always present.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        // Enrichment fetch, on every call. RunInfo carries no free-text field,
        // so the run's date is the value used as the input's text. The result
        // is deliberately discarded: it must not change this node's output.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _ = http_client::fetch(&url);

        SubscriptionList { urls }
    }
}

export!(Node);
